  if(!r||!r.parameters||!MECHANISMS.some(m=>m[0]===r.mechanism)) throw new Error('Unknown shapes recipe');
  const p=r.parameters, v=p.recipe-1, phase=Number.isFinite(t)?clamp(t,0,3):0, enter=smooth(phase/.52), exit=1-smooth((phase-2.52)/.48);
  const alpha=enter*exit, pulse=Math.sin(phase*TAU/1.6), q=phase*TAU/3, body=[];
